-- Blackwing Descent (map 669) — creature_template downport
-- Source: cata_world.creature_template (matched to the CataTC boss scripts).
-- Cross-schema INSERT...SELECT keeping retail entry ids. Idempotent (scoped DELETE first).
--
-- Cata -> AzerothCore(DarkChaos) schema notes:
--   * DarkChaos creature_template DROPPED: scale, HealthScalingExpansion, *ModifierExtra,
--     femaleName, exp_unk, trainer_*, type_flags2, StaticFlags*, mechanic_immune_mask,
--     spell_school_immune_mask. It ADDED: speed_swim, speed_flight, detection_range,
--     dynamicflags, CreatureImmunitiesId.
--   * scale        -> creature_template_model.DisplayScale
--   * modelid1..4  -> creature_template_model (Idx 0..3)   [Cata display ids are PLACEHOLDERS:
--                     remap to the retroported 500xxx CreatureDisplayInfo ids after the model bake]
--   * resistance1..6 -> creature_template_resistance (School 1..6)
--   * spell1..8      -> creature_template_spell (Index 0..7)
--   * LEVEL IS KEPT at the Cata value (88) — this 255-level server's creature_classlevelstats
--     is populated to 255 (matches the Deepholm/Xariona precedent; do NOT down-level).
--   * exp = 2 (WotLK stat scaling); CreatureImmunitiesId = 0 (boss immunities are applied in
--     the C++ encounter, matching Xariona/Oondasta/Thok).
--   * HealthModifier keeps the Cata baseline — BALANCE-TUNE in-game per difficulty.
--   * mechanic_immune_mask is dropped (no column here); re-express via the boss scripts if needed.

-- ---------------------------------------------------------------------------
-- creature_template
-- ---------------------------------------------------------------------------
DELETE FROM `creature_template` WHERE `entry` IN (35592,41270,41376,41378,41379,41442,41445,41505,41546,41570,41576,41620,41767,41789,41806,41841,41843,41879,41948,41961,41962,42098,42166,42178,42179,42180,42186,42321,42347,42356,42362,42595,42649,42690,42733,42764,42767,42768,42800,42802,42803,42856,42897,42920,42934,42947,42949,42951,42954,42956,42958,42960,43119,43122,43125,43126,43127,43128,43129,43130,43206,43296,43404,43407,43656,44202,44418,46083,48270,48964,49226,49416,49427,49447,49580,49623,49679,49740,49799,49811,51089,51506);

INSERT INTO `creature_template`
    (`entry`, `difficulty_entry_1`, `difficulty_entry_2`, `difficulty_entry_3`, `KillCredit1`, `KillCredit2`,
     `name`, `subname`, `IconName`, `gossip_menu_id`, `minlevel`, `maxlevel`, `exp`, `faction`, `npcflag`,
     `speed_walk`, `speed_run`, `speed_swim`, `speed_flight`, `detection_range`, `rank`, `dmgschool`,
     `DamageModifier`, `BaseAttackTime`, `RangeAttackTime`, `BaseVariance`, `RangeVariance`, `unit_class`,
     `unit_flags`, `unit_flags2`, `dynamicflags`, `family`, `type`, `type_flags`, `lootid`, `pickpocketloot`,
     `skinloot`, `PetSpellDataId`, `VehicleId`, `mingold`, `maxgold`, `AIName`, `MovementType`, `HoverHeight`,
     `HealthModifier`, `ManaModifier`, `ArmorModifier`, `ExperienceModifier`, `RacialLeader`, `movementId`,
     `RegenHealth`, `CreatureImmunitiesId`, `flags_extra`, `ScriptName`, `VerifiedBuild`)
SELECT
    ct.`entry`, ct.`difficulty_entry_1`, ct.`difficulty_entry_2`, ct.`difficulty_entry_3`, ct.`KillCredit1`, ct.`KillCredit2`,
    ct.`name`, ct.`subname`, ct.`IconName`, ct.`gossip_menu_id`, ct.`minlevel`, ct.`maxlevel`, 2, ct.`faction`, ct.`npcflag`,
    ct.`speed_walk`, ct.`speed_run`, 1, 1, 20, ct.`rank`, ct.`dmgschool`,
    ct.`DamageModifier`, ct.`BaseAttackTime`, ct.`RangeAttackTime`, ct.`BaseVariance`, ct.`RangeVariance`, ct.`unit_class`,
    ct.`unit_flags`, ct.`unit_flags2`, 0, ct.`family`, ct.`type`, ct.`type_flags`, ct.`lootid`, ct.`pickpocketloot`,
    ct.`skinloot`, ct.`PetSpellDataId`, ct.`VehicleId`, ct.`mingold`, ct.`maxgold`, ct.`AIName`, ct.`MovementType`, ct.`HoverHeight`,
    ct.`HealthModifier`, ct.`ManaModifier`, ct.`ArmorModifier`, ct.`ExperienceModifier`, ct.`RacialLeader`, ct.`movementId`,
    ct.`RegenHealth`, 0, ct.`flags_extra`, ct.`ScriptName`, 0
FROM `cata_world`.`creature_template` ct
WHERE ct.`entry` IN (35592,41270,41376,41378,41379,41442,41445,41505,41546,41570,41576,41620,41767,41789,41806,41841,41843,41879,41948,41961,41962,42098,42166,42178,42179,42180,42186,42321,42347,42356,42362,42595,42649,42690,42733,42764,42767,42768,42800,42802,42803,42856,42897,42920,42934,42947,42949,42951,42954,42956,42958,42960,43119,43122,43125,43126,43127,43128,43129,43130,43206,43296,43404,43407,43656,44202,44418,46083,48270,48964,49226,49416,49427,49447,49580,49623,49679,49740,49799,49811,51089,51506);

-- Flight-flag preservation (see 07_model_movement.sql + the flight investigation):
-- CREATURE_FLAG_EXTRA_NO_MOVE_FLAGS_UPDATE (0x200) lets the scripts own the fly flags so
-- Creature::UpdateMovementFlags does not strip them near the floor between phases.
--   Atramedes 41442 = scripted air phase (highest fall-out-of-sky risk)
--   Magmaw 41570    = stationary disable-gravity vehicle pose
--   Nefarian 41376  = scripted land/takeoff
UPDATE `creature_template` SET `flags_extra` = `flags_extra` | 0x200 WHERE `entry` IN (41442,41570,41376);

